<script setup>
import { $api } from '@/utils/api'

const data = ref({ devices: [], zones: [], reservations: [], intervals: [], commands: [], alerts: [], settings: null, venues: [], sport_codes: [], facilities: [] })
const busy = ref(false), error = ref(''), tab = ref('schedule')
const dialog = reactive({ device: false, channel: false, zone: false, tariff: false, policy: false, operation: false })
const target = ref(null), operation = ref('override')
const device = reactive({ name: '', code: '', provider: 'dry_run', network_host: '', username: '', password: '', enabled: true, dry_run: true })
const channel = reactive({ channel_number: 0, name: '', enabled: true, maximum_continuous_on_minutes: 240 })
const zone = reactive({ venue_id: null, sport_code_id: null, lighting_device_channel_id: null, name: '', code: '', active: true, automatic_control_enabled: false, provider_mode: 'dry_run', pre_start_minutes: 10, post_end_minutes: 5, minimum_billable_minutes: 30, billing_increment_minutes: 30, maximum_continuous_on_minutes: 240, financial_owner_type: 'sport_code', facility_ids: [] })
const tariff = reactive({ name: '', pricing_method: 'fixed', amount_rands: 50, profile: '', starts_at: '', ends_at: '', minimum_minutes: 30, increment_minutes: 30, financial_owner_type: 'sport_code', active: true, priority: 10 })
const policy = reactive({ strategy: 'manual', starts_at: '', ends_at: '', profile: '', active: true, priority: 10 })
const op = reactive({ state: 'on', minutes: 30, reason: '' })
const simulations = ['success', 'retryable_timeout', 'permanent_authentication', 'invalid_response', 'unexpected_on', 'unexpected_off', 'unreachable']
const money = v => new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR' }).format((v || 0) / 100)
const label = v => (v || '').replaceAll('_', ' ')
const availableFacilities = computed(() => data.value.facilities.filter(f => !zone.sport_code_id || f.sport_code_id === zone.sport_code_id))
const channels = computed(() => data.value.devices.flatMap(d => d.channels.map(c => ({ ...c, title: `${d.name} · ${c.name}`, device: d }))))

async function load() { busy.value = true; error.value = ''; try { data.value = await $api('/lighting') } catch (e) { error.value = e?.data?.message || 'Lighting operations could not be loaded.' } finally { busy.value = false } }
async function mutate(url, method, body, close) { busy.value = true; error.value = ''; try { await $api(url, { method, body }); if (close) dialog[close] = false; await load() } catch (e) { error.value = e?.data?.message || Object.values(e?.data?.errors || {})?.flat()?.[0] || 'The lighting change could not be saved.' } finally { busy.value = false } }
const saveDevice = () => mutate('/lighting/devices', 'POST', device, 'device')
function openChannel(d, c = null) { target.value = { device: d, channel: c }; Object.assign(channel, c ? { channel_number: c.channel_number, name: c.name, enabled: c.enabled, maximum_continuous_on_minutes: c.maximum_continuous_on_minutes } : { channel_number: d.channels.length, name: '', enabled: true, maximum_continuous_on_minutes: 240 }); dialog.channel = true }
const saveChannel = () => mutate(`/lighting/devices/${target.value.device.id}/channels${target.value.channel ? `/${target.value.channel.id}` : ''}`, target.value.channel ? 'PUT' : 'POST', channel, 'channel')
function openZone(z = null) { target.value = z; Object.assign(zone, z ? { ...z, facility_ids: z.facilities.map(f => f.id) } : { venue_id: data.value.venues[0]?.id, sport_code_id: data.value.sport_codes[0]?.id, lighting_device_channel_id: null, name: '', code: '', active: true, automatic_control_enabled: false, provider_mode: 'dry_run', pre_start_minutes: 10, post_end_minutes: 5, minimum_billable_minutes: 30, billing_increment_minutes: 30, maximum_continuous_on_minutes: 240, financial_owner_type: 'sport_code', facility_ids: [] }); dialog.zone = true }
const saveZone = () => mutate(`/lighting/zones${target.value ? `/${target.value.id}` : ''}`, target.value ? 'PUT' : 'POST', zone, 'zone')
function openTariff(z) { target.value = z; Object.assign(tariff, { name: '', pricing_method: 'fixed', amount_rands: 50, profile: '', starts_at: '', ends_at: '', minimum_minutes: 30, increment_minutes: 30, financial_owner_type: 'sport_code', active: true, priority: 10 }); dialog.tariff = true }
const saveTariff = () => mutate(`/lighting/zones/${target.value.id}/tariffs`, 'POST', { ...tariff, amount_cents: Math.round(Number(tariff.amount_rands) * 100), profile: tariff.profile || null, starts_at: tariff.starts_at || null, ends_at: tariff.ends_at || null }, 'tariff')
function openPolicy(z) { target.value = z; Object.assign(policy, { strategy: 'manual', starts_at: '', ends_at: '', profile: '', active: true, priority: 10 }); dialog.policy = true }
const savePolicy = () => mutate(`/lighting/zones/${target.value.id}/policies`, 'POST', { ...policy, profile: policy.profile || null, starts_at: policy.starts_at || null, ends_at: policy.ends_at || null }, 'policy')
const simulate = (d, outcome) => mutate(`/lighting/devices/${d.id}/simulation`, 'PUT', { outcome })
const testDevice = d => mutate(`/lighting/devices/${d.id}/test`, 'POST')
const runAction = action => mutate(`/lighting/actions/${action}`, 'POST')
function openOp(type, c) { operation.value = type; target.value = c; op.reason = ''; dialog.operation = true }
const runOp = () => mutate(`/lighting/channels/${target.value.id}/${operation.value === 'emergency' ? 'emergency-off' : 'override'}`, 'POST', { ...op, idempotency_key: crypto.randomUUID() }, 'operation')

onMounted(load)
</script>

<template>
  <div>
    <div class="d-flex flex-wrap justify-space-between align-center gap-3 mb-6"><div><h3 class="text-h3">Court lighting</h3><p class="text-medium-emphasis">Safe dry-run automation, schedules, health, commands and financial reporting.</p></div><div class="d-flex flex-wrap gap-2"><VBtn variant="tonal" @click="dialog.device=true">Add device</VBtn><VBtn @click="openZone()">Add zone</VBtn></div></div>
    <VAlert v-if="error" type="error" closable class="mb-4" @click:close="error=''">{{ error }}</VAlert>
    <VAlert v-if="data.settings" :type="data.settings.dry_run?'info':'warning'" class="mb-4"><strong>{{ data.settings.dry_run?'Dry-run mode':'Live mode' }}</strong> · Automation {{ data.settings.automation_enabled?'enabled':'disabled' }}.</VAlert>
    <VTabs v-model="tab" class="mb-4"><VTab value="schedule">Schedule</VTab><VTab value="devices">Devices & health</VTab><VTab value="zones">Zones & tariffs</VTab><VTab value="commands">Command queue</VTab><VTab value="alerts">Alerts</VTab><VTab value="reports">Reports</VTab></VTabs>
    <VWindow v-model="tab">
      <VWindowItem value="schedule"><VCard><VCardTitle>Planned lighting intervals</VCardTitle><VTable><thead><tr><th>Channel</th><th>On</th><th>Off</th><th>Bookings</th><th>Status</th></tr></thead><tbody><tr v-for="i in data.intervals" :key="i.id"><td>{{ i.channel?.device?.name }} · {{ i.channel?.name }}</td><td>{{ new Date(i.starts_at).toLocaleString() }}</td><td>{{ new Date(i.ends_at).toLocaleString() }}</td><td>{{ i.reservations?.map(r=>r.booking?.booking_reference).join(', ') }}</td><td>{{ label(i.status) }}</td></tr></tbody></VTable></VCard></VWindowItem>
      <VWindowItem value="devices"><div class="d-flex flex-wrap gap-2 mb-4"><VBtn size="small" variant="tonal" :loading="busy" @click="runAction('health')">Run health check</VBtn><VBtn size="small" variant="tonal" :loading="busy" @click="runAction('reconcile')">Run reconciliation</VBtn></div><VRow><VCol v-for="d in data.devices" :key="d.id" cols="12" md="6"><VCard><VCardTitle>{{ d.name }}</VCardTitle><VCardText><p>{{ d.code }} · {{ d.provider }} · {{ d.dry_run?'dry run':'live gated' }}</p><p>Health: {{ label(d.last_health_status) }} · Credentials: {{ d.credentials_configured?'configured':'not configured' }}</p><VSelect v-if="d.dry_run" :model-value="d.provider_settings?.dry_run_outcome||'success'" :items="simulations" label="Dry-run outcome" @update:model-value="v=>simulate(d,v)"/><div v-for="c in d.channels" :key="c.id" class="border rounded pa-3 mb-2"><div class="d-flex flex-wrap justify-space-between gap-2"><div><strong>{{ c.channel_number }} · {{ c.name }}</strong><div class="text-caption">{{ c.enabled?'Enabled':'Disabled' }} · {{ label(c.last_known_state) }} · max {{ c.maximum_continuous_on_minutes }} min</div><div v-if="c.zones?.length" class="text-caption">Mapped: {{ c.zones.map(z=>z.name).join(', ') }}</div></div><div><VBtn size="x-small" variant="text" @click="openChannel(d,c)">Edit</VBtn><VBtn size="x-small" variant="text" @click="openOp('override',c)">Override</VBtn><VBtn size="x-small" color="error" variant="text" @click="openOp('emergency',c)">Emergency off</VBtn></div></div></div><div class="d-flex gap-2"><VBtn size="small" variant="tonal" @click="openChannel(d)">Add channel</VBtn><VBtn size="small" variant="tonal" :disabled="!d.channels.length" @click="testDevice(d)">Test connection</VBtn></div></VCardText></VCard></VCol></VRow></VWindowItem>
      <VWindowItem value="zones"><VRow><VCol v-for="z in data.zones" :key="z.id" cols="12" md="6"><VCard><VCardTitle class="d-flex"><span>{{ z.name }}</span><VSpacer/><VBtn size="small" variant="text" @click="openZone(z)">Edit</VBtn></VCardTitle><VCardText><p>{{ z.code }} · {{ label(z.provider_mode) }} · {{ z.active?'active':'disabled' }}</p><p>Facilities: {{ z.facilities?.map(f=>f.name).join(', ')||'None' }}</p><p>Buffers: -{{ z.pre_start_minutes }} / +{{ z.post_end_minutes }} minutes</p><div class="mb-3"><strong>Tariffs</strong><VChip v-for="t in z.tariffs" :key="t.id" class="ma-1" size="small">{{ t.name }} · {{ money(t.amount_cents) }} · P{{ t.priority }}</VChip></div><div class="mb-3"><strong>Policies</strong><VChip v-for="p in z.policies" :key="p.id" class="ma-1" size="small">{{ label(p.strategy) }} · P{{ p.priority }}</VChip></div><VBtn size="small" variant="tonal" @click="openTariff(z)">Add tariff</VBtn><VBtn size="small" variant="text" @click="openPolicy(z)">Add requirement policy</VBtn></VCardText></VCard></VCol></VRow></VWindowItem>
      <VWindowItem value="commands"><div class="mb-3"><VBtn size="small" :loading="busy" @click="runAction('dispatch')">Dispatch due commands</VBtn></div><VCard><VTable><thead><tr><th>Due</th><th>Device</th><th>Command</th><th>Status</th><th>Attempts</th><th>Safe result</th></tr></thead><tbody><tr v-for="c in data.commands" :key="c.id"><td>{{ new Date(c.due_at).toLocaleString() }}</td><td>{{ c.channel?.device?.name }}</td><td>{{ label(c.command_type) }}</td><td>{{ label(c.status) }}</td><td>{{ c.attempt_count }}</td><td>{{ label(c.safe_error_code||c.provider_result_code) }}</td></tr></tbody></VTable></VCard></VWindowItem>
      <VWindowItem value="alerts"><VCard><VList><VListItem v-for="a in data.alerts" :key="a.id" :title="label(a.alert_type)" :subtitle="a.safe_message"><template #append><VChip :color="a.severity==='critical'?'error':'warning'">{{ a.status }}</VChip></template></VListItem></VList></VCard></VWindowItem>
      <VWindowItem value="reports"><VRow><VCol cols="12" md="4"><VCard><VCardTitle>Reservations</VCardTitle><VCardText class="text-h3">{{ data.reservations.length }}</VCardText></VCard></VCol><VCol cols="12" md="4"><VCard><VCardTitle>Lighting booked</VCardTitle><VCardText class="text-h3">{{ money(data.reservations.reduce((s,r)=>s+r.amount,0)) }}</VCardText></VCard></VCol><VCol cols="12" md="4"><VCard><VCardTitle>Open alerts</VCardTitle><VCardText class="text-h3">{{ data.alerts.filter(a=>a.status==='open').length }}</VCardText></VCard></VCol></VRow></VWindowItem>
    </VWindow>

    <VDialog v-model="dialog.device" max-width="680"><VCard><VCardTitle>Add safe lighting device</VCardTitle><VCardText><VTextField v-model="device.name" label="Name"/><VTextField v-model="device.code" label="Code"/><VSelect v-model="device.provider" :items="['dry_run','manual','shelly']" label="Provider"/><VTextField v-model="device.network_host" label="Verified local host (optional in dry run)"/><VTextField v-model="device.username" autocomplete="new-password" label="Username (write only)"/><VTextField v-model="device.password" type="password" autocomplete="new-password" label="Password (write only)"/><VSwitch v-model="device.dry_run" label="Dry run"/><VAlert type="info" variant="tonal">Live operation remains safety-gated.</VAlert></VCardText><VCardActions><VSpacer/><VBtn variant="tonal" @click="dialog.device=false">Close</VBtn><VBtn :loading="busy" :disabled="busy" @click="saveDevice">Save</VBtn></VCardActions></VCard></VDialog>
    <VDialog v-model="dialog.channel" max-width="600"><VCard><VCardTitle>{{ target?.channel?'Edit':'Add' }} controller channel</VCardTitle><VCardText><VTextField v-model.number="channel.channel_number" type="number" label="Channel number"/><VTextField v-model="channel.name" label="Name"/><VSwitch v-model="channel.enabled" label="Enabled"/><VTextField v-model.number="channel.maximum_continuous_on_minutes" type="number" label="Maximum continuous-on minutes"/><VAlert v-if="target?.channel?.zones?.length" type="warning" variant="tonal">Mapped zones: {{ target.channel.zones.map(z=>z.name).join(', ') }}</VAlert></VCardText><VCardActions><VSpacer/><VBtn variant="tonal" @click="dialog.channel=false">Close</VBtn><VBtn :loading="busy" :disabled="busy||!channel.name" @click="saveChannel">Save channel</VBtn></VCardActions></VCard></VDialog>
    <VDialog v-model="dialog.zone" max-width="760"><VCard><VCardTitle>{{ target?'Edit':'Add' }} lighting zone</VCardTitle><VCardText><VTextField v-model="zone.name" label="Name"/><VTextField v-model="zone.code" label="Code"/><VSelect v-model="zone.sport_code_id" :items="data.sport_codes" item-title="name" item-value="id" label="Sport code"/><VSelect v-model="zone.venue_id" :items="data.venues" item-title="name" item-value="id" label="Venue"/><VSelect v-model="zone.facility_ids" :items="availableFacilities" item-title="name" item-value="id" label="Facilities" multiple chips/><VSelect v-model="zone.lighting_device_channel_id" :items="channels" item-title="title" item-value="id" label="Controller channel" clearable/><VSelect v-model="zone.provider_mode" :items="['dry_run','manual','shelly']" label="Provider mode"/><VRow><VCol cols="6"><VTextField v-model.number="zone.pre_start_minutes" type="number" label="Pre-start minutes"/></VCol><VCol cols="6"><VTextField v-model.number="zone.post_end_minutes" type="number" label="Post-end minutes"/></VCol><VCol cols="6"><VTextField v-model.number="zone.minimum_billable_minutes" type="number" label="Minimum billable minutes"/></VCol><VCol cols="6"><VTextField v-model.number="zone.billing_increment_minutes" type="number" label="Billing increment minutes"/></VCol><VCol cols="6"><VTextField v-model.number="zone.maximum_continuous_on_minutes" type="number" label="Maximum continuous-on minutes"/></VCol><VCol cols="6"><VSelect v-model="zone.financial_owner_type" :items="['sport_code','central_hsc']" label="Financial owner"/></VCol></VRow><VSwitch v-model="zone.automatic_control_enabled" label="Automatic control"/><VSwitch v-model="zone.active" label="Active"/><VAlert v-if="target?.reservations_count" type="warning">This change affects {{ target.reservations_count }} future reservations.</VAlert></VCardText><VCardActions><VSpacer/><VBtn variant="tonal" @click="dialog.zone=false">Close</VBtn><VBtn :loading="busy" :disabled="busy" @click="saveZone">Save zone</VBtn></VCardActions></VCard></VDialog>
    <VDialog v-model="dialog.tariff" max-width="680"><VCard><VCardTitle>Add tariff · {{ target?.name }}</VCardTitle><VCardText><VTextField v-model="tariff.name" label="Name"/><VSelect v-model="tariff.pricing_method" :items="['fixed','hourly','per_minute']" label="Pricing method"/><VTextField v-model.number="tariff.amount_rands" type="number" min="0" label="Amount (ZAR)"/><VRow><VCol><VTextField v-model="tariff.starts_at" type="time" label="Starts"/></VCol><VCol><VTextField v-model="tariff.ends_at" type="time" label="Ends"/></VCol></VRow><VTextField v-model.number="tariff.minimum_minutes" type="number" label="Minimum minutes"/><VTextField v-model.number="tariff.increment_minutes" type="number" label="Billing increment"/><VTextField v-model.number="tariff.priority" type="number" label="Priority"/><VSelect v-model="tariff.financial_owner_type" :items="['sport_code','central_hsc']" label="Financial owner"/><VSwitch v-model="tariff.active" label="Active"/></VCardText><VCardActions><VSpacer/><VBtn variant="tonal" @click="dialog.tariff=false">Close</VBtn><VBtn :loading="busy" :disabled="busy||!tariff.name" @click="saveTariff">Save tariff</VBtn></VCardActions></VCard></VDialog>
    <VDialog v-model="dialog.policy" max-width="680"><VCard><VCardTitle>Add requirement policy · {{ target?.name }}</VCardTitle><VCardText><VSelect v-model="policy.strategy" :items="[{title:'Optional',value:'manual'},{title:'Required in time band',value:'fixed_band'},{title:'Always required',value:'always_required'},{title:'Prohibited',value:'never_available'}]" label="Requirement"/><VRow v-if="policy.strategy==='fixed_band'"><VCol><VTextField v-model="policy.starts_at" type="time" label="Required from"/></VCol><VCol><VTextField v-model="policy.ends_at" type="time" label="Required until"/></VCol></VRow><VTextField v-model="policy.profile" label="Profile (optional)"/><VTextField v-model.number="policy.priority" type="number" label="Priority"/><VSwitch v-model="policy.active" label="Active"/><VAlert type="info" variant="tonal">{{ policy.strategy==='fixed_band'?`Lighting is required from ${policy.starts_at||'the configured time'} to closing.`:policy.strategy==='never_available'?'Lighting is disabled for maintenance.':policy.strategy==='always_required'?'Lighting is always required.':'Lighting is optional for this court.' }}</VAlert></VCardText><VCardActions><VSpacer/><VBtn variant="tonal" @click="dialog.policy=false">Close</VBtn><VBtn :loading="busy" :disabled="busy" @click="savePolicy">Save policy</VBtn></VCardActions></VCard></VDialog>
    <VDialog v-model="dialog.operation" max-width="580"><VCard><VCardTitle>{{ operation==='emergency'?'Emergency switch-off':'Timed manual override' }}</VCardTitle><VCardText><VSelect v-if="operation!=='emergency'" v-model="op.state" :items="['on','off']" label="State"/><VTextField v-if="operation!=='emergency'" v-model.number="op.minutes" type="number" label="Duration (minutes)"/><VTextarea v-model="op.reason" label="Reason"/><VAlert :type="operation==='emergency'?'error':'warning'" variant="tonal">{{ operation==='emergency'?'Pending switch-ons will be superseded. No automatic refund is made.':'Automation is suspended until this override expires.' }}</VAlert></VCardText><VCardActions><VSpacer/><VBtn variant="tonal" @click="dialog.operation=false">Close</VBtn><VBtn :color="operation==='emergency'?'error':'primary'" :loading="busy" :disabled="busy||op.reason.length<3" @click="runOp">Confirm</VBtn></VCardActions></VCard></VDialog>
  </div>
</template>
